w('src/analyticsInsights.ts',r'''import type {AnalyticsPoint,AnalyticsTopVideo,ChannelAnalytics} from './types';
export type AnalyticsDelta={current:number;previous:number;delta:number;percent?:number};
export type AnalyticsInsight={tone:'good'|'warn'|'info';title:string;text:string;metric?:string};
const total=(rows:AnalyticsPoint[],key:'views'|'watchMinutes'|'estimatedRevenue')=>rows.reduce((n,x)=>n+Number(x[key]||0),0);
const change=(current:number,previous:number):AnalyticsDelta=>({current,previous,delta:current-previous,percent:previous?((current-previous)/previous*100):undefined});
export function analyticsWindow(a:ChannelAnalytics|undefined,days=7){const rows=a?.daily||[];const current=rows.slice(-days),previous=rows.slice(-(days*2),-days);return{current,previous,views:change(total(current,'views'),total(previous,'views')),watch:change(total(current,'watchMinutes'),total(previous,'watchMinutes')),revenue:change(total(current,'estimatedRevenue'),total(previous,'estimatedRevenue'))}}
export function analyticsInsights(a:ChannelAnalytics|undefined):AnalyticsInsight[]{if(!a)return[];const w=analyticsWindow(a,7),out:AnalyticsInsight[]=[];if(w.views.previous&&w.views.percent!=null)out.push({tone:w.views.percent>=0?'good':'warn',title:w.views.percent>=0?'Просмотры ускоряются':'Просмотры снизились',text:`Последние 7 дней: ${w.views.percent>=0?'+':''}${w.views.percent.toFixed(1)}% к предыдущим 7 дням.`,metric:`${Math.round(w.views.current).toLocaleString('ru-RU')} views`});if(a.averageViewPercentage>0&&a.averageViewPercentage<30)out.push({tone:'warn',title:'Удержание требует внимания',text:`Средний просмотр ${a.averageViewPercentage.toFixed(1)}%. Сначала улучшайте первые минуты и структуру ролика.`});else if(a.averageViewPercentage>=45)out.push({tone:'good',title:'Сильное удержание',text:`Средний просмотр ${a.averageViewPercentage.toFixed(1)}%. Этот формат стоит масштабировать.`});if(a.impressionCtr!=null){if(a.impressionCtr<3)out.push({tone:'warn',title:'CTR низкий',text:`CTR ${a.impressionCtr.toFixed(2)}%. Проверьте thumbnail/title у роликов с большим числом показов.`});else if(a.impressionCtr>=6)out.push({tone:'good',title:'CTR сильный',text:`CTR ${a.impressionCtr.toFixed(2)}%. Сохраняйте текущую упаковку.`})}const top=(a.topVideos||[]).slice().sort((x,y)=>Number(y.views||0)-Number(x.views||0))[0];if(top)out.push({tone:'info',title:'Лидер по просмотрам',text:`«${top.title}» — ${Number(top.views||0).toLocaleString('ru-RU')} просмотров. Используйте тему/формат как ориентир следующей партии.`});const bestRpm=(a.topVideos||[]).filter(x=>Number.isFinite(x.rpm)&&Number(x.rpm)>0).sort((x,y)=>Number(y.rpm||0)-Number(x.rpm||0))[0];if(bestRpm)out.push({tone:'info',title:'Лучший RPM среди сохранённых видео',text:`«${bestRpm.title}» — $${Number(bestRpm.rpm).toFixed(2)} RPM. Приоритет этой темы имеет смысл, если удержание также не ниже среднего.`});return out.slice(0,6)}
export function bestTopVideo(rows:AnalyticsTopVideo[]=[]){return rows.slice().sort((a,b)=>Number(b.views||0)-Number(a.views||0))[0]}
''')

