w('src/competitorInsights.ts',r'''import type {Competitor,CompetitorVideo} from './types';
export type CompetitorInsight={competitorId:string;score:number;title:string;reason:string;terms:string[];cadenceDays?:number};
const stop=new Set(['the','and','for','with','this','that','you','your','mix','music','official','video','playlist','live','new','best','для','как','это','или','под','при','без','видео','музыка','микс']);
function terms(videos:CompetitorVideo[]=[]){const m=new Map<string,number>();for(const v of videos){for(const raw of v.title.toLocaleLowerCase('ru-RU').split(/[^\p{L}\p{N}]+/u)){const x=raw.trim();if(x.length<3||stop.has(x)||/^\d+$/.test(x))continue;m.set(x,(m.get(x)||0)+1)}}return [...m].sort((a,b)=>b[1]-a[1]).slice(0,5).map(x=>x[0])}
function cadence(videos:CompetitorVideo[]=[]){const ds=videos.map(x=>Date.parse(x.publishedAt||'')).filter(Number.isFinite).sort((a,b)=>b-a);if(ds.length<2)return undefined;const gaps=[] as number[];for(let i=0;i<ds.length-1;i++)gaps.push(Math.max(.1,(ds[i]-ds[i+1])/86400000));return gaps.reduce((a,b)=>a+b,0)/gaps.length}
export function competitorOpportunity(c:Competitor):CompetitorInsight{const avg=Math.max(0,Number(c.recentAverageViews||0)),subs=Math.max(1,Number(c.subscribers||1)),ratio=avg/subs,sim=Math.max(0,Math.min(100,Number(c.similarity||0)))/100,recency=c.lastVideoAt?Math.max(0,1-Math.min(30,(Date.now()-Date.parse(c.lastVideoAt))/86400000)/30):.2,score=Math.round(Math.min(100,(ratio*55+sim*30+recency*15)*100)/100);const t=terms(c.latestVideos),cd=cadence(c.latestVideos);return{competitorId:c.id,score,title:score>=70?'Высокий приоритет для анализа':score>=45?'Есть рабочие сигналы':'Наблюдать',reason:`Recent Avg / Subscribers: ${(ratio*100).toFixed(1)}%${c.similarity!=null?` • Similarity ${c.similarity}%`:''}${cd?` • публикация ≈ раз в ${cd.toFixed(1)} дн.`:''}`,terms:t,cadenceDays:cd}}
export function competitorInsights(list:Competitor[]){return list.map(competitorOpportunity).sort((a,b)=>b.score-a.score)}
export function sharedWinningTerms(list:Competitor[]){const m=new Map<string,number>();for(const x of list){for(const t of competitorOpportunity(x).terms)m.set(t,(m.get(t)||0)+1)}return[...m].sort((a,b)=>b[1]-a[1]).slice(0,8).map(([term,count])=>({term,count}))}
''')

